"""Bundle topology events computed before rounding interpolated world positions.

Subtracting two independently interpolated coordinates can turn a small signed
gap into a false zero interval. That introduces duplicate contact anchors and
sliver rows. Instead evaluate the difference from nearby segment endpoints:
    (base_b - base_a) + (residual_b - residual_a).
The original boundary curves and their emitted world positions are unchanged.
No gap tolerance, event clustering, or suppression of real crossings is used.
"""
import bpy
from .path_surface_nodes import _Nodes
from . import bundle_axis_nodes as axis

NAME = 'Prochitecture Streets / Local-difference Bundle events v1'


def differences(g, curves, metric, lateral):
    index = g.node('GeometryNodeInputIndex', 'Certified boundary knot address').outputs[0]
    position = g.named('st_axis_xy', 'FLOAT_VECTOR')
    knot = g.named('st_bundle_metric', 'FLOAT')
    bases, residuals = [], []
    for k, curve in enumerate(curves):
        lookup = g.node('GeometryNodeSampleCurve', 'Boundary segment address '+str(k))
        lookup.mode = 'LENGTH'; lookup.data_type = 'FLOAT'
        g.set(curve, lookup.inputs['Curves']); g.set(metric, lookup.inputs['Length'])
        g.set(index, lookup.inputs['Value'])
        count = axis._size(g, curve, 'CURVE')
        first = g.math('MAXIMUM', 0., g.math('MINIMUM', g.math('SUBTRACT', count, 2.),
            g.math('FLOOR', lookup.outputs['Value'])))
        second = g.math('ADD', first, 1.)
        a, b = [g.sample(curve, position, i, 'FLOAT_VECTOR') for i in (first, second)]
        sa, sb = [g.sample(curve, knot, i, 'FLOAT') for i in (first, second)]
        # Use the nearer endpoint to avoid losing a small residual at t=1.
        nearer_b = g.compare(g.math('SUBTRACT', metric, sa), g.math('SUBTRACT', sb, metric), 'GREATER_THAN')
        base = g.switch(nearer_b, a, b, 'VECTOR')
        origin = g.switch(nearer_b, sa, sb)
        fraction = g.math('DIVIDE', g.math('SUBTRACT', metric, origin), g.math('SUBTRACT', sb, sa))
        bases.append(base)
        residuals.append(g.vector('SCALE', g.vector('SUBTRACT', b, a), fraction))
    values = []
    for a, b in ((2, 1), (2, 0), (1, 3)):
        delta = g.vector('ADD', g.vector('SUBTRACT', bases[a], bases[b]),
            g.vector('SUBTRACT', residuals[a], residuals[b]))
        values.append(g.vector('DOT_PRODUCT', delta, lateral))
    return values


def build():
    if NAME in bpy.data.node_groups:
        return bpy.data.node_groups[NAME]
    tree = bpy.data.node_groups.new(NAME, 'GeometryNodeTree'); g = _Nodes(tree)
    for name, kind in [('Boundary '+str(k), 'Geometry') for k in range(4)]+[
            ('Mandatory', 'Geometry'), ('Lateral', 'Vector'), ('Minimum Separator Width', 'Float')]:
        tree.interface.new_socket(name=name, in_out='INPUT', socket_type='NodeSocket'+kind)
    tree.interface.new_socket(name='Geometry', in_out='OUTPUT', socket_type='NodeSocketGeometry')
    inp = g.node('NodeGroupInput', 'Certified boundaries and complete scalar knot union')
    out = g.node('NodeGroupOutput', 'All strict crossings and exact touches')
    curves = [inp.outputs['Boundary '+str(k)] for k in range(4)]
    mandatory = inp.outputs['Mandatory']; count = axis._size(g, mandatory)
    index = g.node('GeometryNodeInputIndex', 'Original knot or interval').outputs[0]
    metric = g.named('st_bundle_metric', 'FLOAT')
    sa = g.sample(mandatory, metric, index, 'FLOAT')
    sb = g.sample(mandatory, metric, g.math('ADD', index, 1.), 'FLOAT')
    a, b, at = [differences(g, curves, s, inp.outputs['Lateral']) for s in (sa, sb, metric)]
    events = []
    minimum = inp.outputs['Minimum Separator Width']
    for kind in range(6):
        pair = 0 if kind < 2 or kind >= 4 else kind-1
        threshold = minimum if kind == 1 else g.math('MULTIPLY', -2. if kind == 4 else 2., minimum) if kind >= 4 else 0.
        fa, fb, value = [g.math('SUBTRACT', v[pair], threshold) for v in (a, b, at)]
        line = g.node('GeometryNodeMeshLine', 'Possible exact event '+str(kind))
        g.set(g.math('MAXIMUM', 1., g.math('SUBTRACT', count, 1.)), line.inputs['Count'])
        crossing = g.compare(g.math('MULTIPLY', fa, fb), 0., 'LESS_THAN')
        fraction = g.math('DIVIDE', fa, g.math('SUBTRACT', fa, fb))
        location = g.math('ADD', sa, g.math('MULTIPLY', fraction, g.math('SUBTRACT', sb, sa)))
        part = g.store(line.outputs['Mesh'], 'st_bundle_metric', location)
        part = g.store(part, 'st_bundle_gap_event', kind+1, 'INT')
        events.append(axis._select(g, part, crossing, 'Strict local-difference crossing'))
        previous = g.sample(mandatory, value, g.math('MAXIMUM', 0., g.math('SUBTRACT', index, 1.)), 'FLOAT')
        following = g.sample(mandatory, value, g.math('MINIMUM', g.math('SUBTRACT', count, 1.), g.math('ADD', index, 1.)), 'FLOAT')
        zero = g.compare(g.math('ABSOLUTE', value), 0., 'LESS_EQUAL')
        boundary = g.either(g.compare(g.math('ABSOLUTE', previous), 0., 'GREATER_THAN'),
                           g.compare(g.math('ABSOLUTE', following), 0., 'GREATER_THAN'))
        part = g.store(mandatory, 'st_bundle_gap_event', kind+1, 'INT')
        events.append(axis._select(g, part, g.all(zero, boundary), 'Exact local-difference threshold touch'))
    g.set(axis._join(g, *events), out.inputs['Geometry'])
    return tree


def evaluate(g, curves, mandatory, lateral, minimum_band):
    node = g.node('GeometryNodeGroup', 'Certified local-difference Bundle topology events')
    node.node_tree = build()
    for k, curve in enumerate(curves):
        g.set(curve, node.inputs['Boundary '+str(k)])
    for name, value in (('Mandatory', mandatory), ('Lateral', lateral), ('Minimum Separator Width', minimum_band)):
        g.set(value, node.inputs[name])
    return node.outputs['Geometry']


def narrow_cap_active(g, active, boundaries, lateral):
    """Initial rollout: the finite contact/narrow-infill terminal family only."""
    physical = g.named('st_axis_xy', 'FLOAT_VECTOR')
    gaps = []
    for end in (False, True):
        endpoints = [g.sample(boundary, physical,
            g.math('SUBTRACT', axis._size(g, boundary), 1.) if end else 0, 'FLOAT_VECTOR')
            for boundary in boundaries[1:3]]
        gap = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', endpoints[1], endpoints[0]), lateral)
        gaps.append(g.compare(gap, 0., 'GREATER_EQUAL'))
    return g.all(active, g.either(*gaps))


def install_saved(original):
    """Replace legacy event discovery with the canonical helper in a saved v45.

    All users of the old event collection are rewired, including the legacy
    mesh-row table. This only avoids rebuilding the unchanged parent graph;
    the normal constructor above invokes exactly the same shared helper.
    """
    if original.get('st_bundle_finite_terminal_contact') != 1:
        raise ValueError('Require a saved finite-contact Bundle constructor')
    from . import bundle_nodes
    tree = original.copy(); tree.name = bundle_nodes.SURFACE+' / Finite narrow caps and local events v1'
    g = _Nodes(tree)
    selectors = [n for n in tree.nodes if n.label in (
        'All strict linear gap or containment transitions',
        'Exact threshold touch or constant-threshold interval end')]
    if len(selectors) != 12:
        raise ValueError('Unexpected legacy event-discovery contract')
    touch = next(n for n in selectors if n.label.startswith('Exact threshold'))
    store, = [l.from_node for l in touch.inputs['Geometry'].links]
    mandatory, = [l.from_socket for l in store.inputs['Geometry'].links]
    lookup = next(n for n in tree.nodes if n.label == 'Shared certified Bundle boundary interpolation')
    curves = [n.links[0].from_socket for n in lookup.inputs if n.name.startswith('Boundary ')]
    cap, = [n for n in tree.nodes if n.label == 'Profiled start cap']
    minimum, = [l.from_socket for l in cap.inputs['Minimum Separator Width'].links]
    if mandatory.node.bl_idname != 'GeometryNodeStoreNamedAttribute' or mandatory.node.inputs['Name'].default_value != 'st_bundle_gap':
        raise ValueError('Missing original mandatory gap field')
    gap, = [l.from_node for l in mandatory.node.inputs['Value'].links]
    if gap.bl_idname != 'ShaderNodeVectorMath' or gap.operation != 'DOT_PRODUCT':
        raise ValueError('Missing original signed lateral direction')
    lateral, = [l.from_socket for l in gap.inputs[1].links]
    replacement = evaluate(g, curves, mandatory, lateral, minimum)
    old_links = [link for link in tree.links if link.from_node in selectors]
    targets = {link.to_socket for link in old_links}
    if not targets or any(s.node.bl_idname != 'GeometryNodeJoinGeometry' for s in targets):
        raise ValueError('Unexpected consumers of legacy event records')
    active_node, = [n for n in tree.nodes if n.bl_idname == 'GeometryNodeStoreNamedAttribute'
                   and n.inputs['Name'].default_value == 'st_bundle_free_cap_body']
    active, = [l.from_socket for l in active_node.inputs['Value'].links]
    boundaries = [cap.inputs['Boundary '+str(k)].links[0].from_socket for k in range(4)]
    active = narrow_cap_active(g, active, boundaries, lateral)
    previous = axis._join(g, *(n.outputs['Selection'] for n in selectors))
    replacement = g.switch(active, previous, replacement, 'GEOMETRY',
        'Local-difference events for finite narrow terminal caps')
    for link in old_links:
        tree.links.remove(link)
    for socket in targets:
        g.set(replacement, socket)
    tree['st_bundle_local_difference_events'] = 1
    return tree
